"""
Main routing logic for processing calls and dispatching agents
"""

import json
from typing import Any
from typing import Dict
from typing import Optional

from livekit.agents import JobContext

from commons.enums import AgentType
from commons.monitoring import AgentMonitoring
from commons.monitoring import logging
from commons.schemas.config import EnvironmentConfig
from commons.schemas.ingest import CallKind
from commons.schemas.ingest import InboundInputMetadata
from commons.schemas.ingest import InputMetadata
from commons.schemas.ingest import OutboundInputMetadata
from commons.schemas.ingest import ParticipantMetadata
from commons.schemas.ingest import PlaygroundInputMetadata
from commons.schemas.ingest import ScreeningAgentRoomMetadata
from commons.schemas.ingest import SIPParticipantMetadata
from commons.schemas.ingest import StandardParticipantMetadata
from commons.schemas.ingest import WebInputMetadata
from commons.schemas.purplefish import CreateEngagementResponse
from commons.services.livekit_client import LiveKitClient
from commons.services.purplefish_client import PurplefishClient


logger = logging.get_logger(__name__)


class RoutingAgent:
    """Handles routing logic for incoming calls"""

    def __init__(
        self,
        ctx: JobContext,
        environment_config: EnvironmentConfig,
        agent_monitor: AgentMonitoring,
        purplefish_client: PurplefishClient,
    ):
        self.ctx = ctx
        self.environment_config = environment_config
        self.tracer = agent_monitor.agent_tracer.get_tracer(__name__)
        self.livekit_client = LiveKitClient(
            environment_config.livekit_url,
            environment_config.secrets.livekit_api_key.get_secret_value(),
            environment_config.secrets.livekit_api_secret.get_secret_value(),
            agent_monitor.agent_tracer,
        )
        self.room_name = ctx.room.name

        # Use provided purplefish client or create new one
        self.purplefish_client = purplefish_client

        # Log initialization
        logger.info(
            "RoutingAgent initialized",
            extra={
                "room_name": self.room_name,
                "job_id": ctx.job.id if ctx.job else None,
                "agent_type": AgentType.ROUTING,
                "environment": environment_config.agent_env,
            },
        )

    async def route(self) -> None:
        """Main routing logic with comprehensive tracing"""
        with self.tracer.start_as_current_span("routing_agent.route") as span:
            span.set_attribute("job_id", self.ctx.job.id)
            span.set_attribute("agent.type", AgentType.ROUTING)

            logger.info(
                "Starting routing process",
                extra={
                    "room_name": self.room_name,
                    "job_id": self.ctx.job.id,
                },
            )

            try:
                # Step 1: Check room metadata first
                with self.tracer.start_as_current_span(
                    "routing.get_metadata"
                ) as step_span:
                    room_metadata = await self._get_current_metadata()
                    step_span.set_attribute("has_metadata", room_metadata is not None)
                    if room_metadata:
                        step_span.set_attribute(
                            "metadata.opportunity_id",
                            getattr(room_metadata, "opportunity_id", ""),
                        )

                # Step 2: Only check participants if room metadata is missing required data
                participant_data = None
                if self._needs_participant_data(room_metadata):
                    with self.tracer.start_as_current_span(
                        "routing.get_participant_data"
                    ) as step_span:
                        participant_data = await self._get_participant_data()
                        step_span.set_attribute(
                            "has_participant_data", participant_data is not None
                        )
                        if participant_data:
                            step_span.set_attribute(
                                "participant.type",
                                getattr(
                                    participant_data, "participant_type", "unknown"
                                ),
                            )
                else:
                    logger.info(
                        "Skipping participant check - room metadata is sufficient",
                        extra={
                            "room_name": self.room_name,
                            "has_opportunity_id": bool(
                                room_metadata and room_metadata.get("opportunity_id")
                            ),
                        },
                    )

                # Step 3: Build appropriate input metadata based on all available data
                with self.tracer.start_as_current_span(
                    "routing.build_metadata"
                ) as step_span:
                    input_metadata = self._build_final_metadata(
                        room_metadata, participant_data
                    )
                    step_span.set_attribute("metadata.kind", input_metadata.kind)

                # Step 4: Create engagement with Purplefish
                with self.tracer.start_as_current_span(
                    "routing.create_engagement"
                ) as step_span:
                    engagement_result = await self._create_engagement(input_metadata)
                    engagement_id = ""
                    if engagement_result:
                        engagement_id = engagement_result.engagement_id
                        # Update agent to the one returned by Purplefish if provided
                        if engagement_result.agent_name:
                            # Convert string agent_name to AgentType enum
                            try:
                                input_metadata.agent = AgentType(
                                    engagement_result.agent_name
                                )
                            except ValueError:
                                logger.warning(
                                    "Unknown agent type from Purplefish, using default",
                                    extra={
                                        "agent_name": engagement_result.agent_name,
                                        "default_agent": AgentType.SCREENING,
                                    },
                                )
                                input_metadata.agent = AgentType.SCREENING
                            step_span.set_attribute(
                                "agent.name", engagement_result.agent_name
                            )
                        else:
                            # Keep the default agent if no agent_name provided
                            logger.info(
                                "No agent_name in engagement response, using default",
                                extra={
                                    "default_agent": input_metadata.agent,
                                },
                            )
                        step_span.set_attribute("engagement.id", engagement_id)
                    else:
                        # Default to screening agent if no engagement created
                        input_metadata.agent = AgentType.SCREENING

                # Step 5: Create AgentRoomMetadata by combining input and participant metadata
                with self.tracer.start_as_current_span(
                    "routing.create_agent_metadata"
                ) as step_span:
                    agent_room_metadata = self._create_agent_room_metadata(
                        input_metadata=input_metadata,
                        participant_metadata=participant_data,
                        engagement_id=engagement_id,
                    )
                    step_span.set_attribute("has_engagement_id", bool(engagement_id))

                # Step 6: Update room metadata with AgentRoomMetadata
                with self.tracer.start_as_current_span("routing.update_metadata"):
                    await self._update_room_metadata(agent_room_metadata)

                # Step 7: Dispatch agent with AgentRoomMetadata
                with self.tracer.start_as_current_span(
                    "routing.dispatch_agent"
                ) as step_span:
                    await self._dispatch_agent(agent_room_metadata)
                    step_span.set_attribute(
                        "agent.dispatched", input_metadata.agent or AgentType.SCREENING
                    )

                span.set_attribute("routing.success", True)
                logger.info(
                    "Routing completed successfully",
                    extra={
                        "room_name": self.room_name,
                        "call_kind": input_metadata.kind,
                        "engagement_id": engagement_id,
                        "job_id": self.ctx.job.id,
                    },
                )

            except Exception as e:
                span.set_attribute("routing.success", False)
                span.set_attribute("error.type", type(e).__name__)
                span.set_attribute("error.message", str(e))
                logger.error(
                    "Routing failed",
                    extra={
                        "room_name": self.room_name,
                        "job_id": self.ctx.job.id if self.ctx.job else None,
                        "error_type": type(e).__name__,
                    },
                    exc_info=True,
                )
                raise e

    def _needs_participant_data(self, room_metadata: Optional[InputMetadata]) -> bool:
        """Check if we need to fetch participant data based on room metadata"""
        if not room_metadata:
            # No room metadata, need to check participants
            return True

        # Check if room metadata has sufficient information for engagement creation
        has_opportunity_id = bool(getattr(room_metadata, "opportunity_id", None))
        has_phone_numbers = bool(
            getattr(room_metadata, "candidate_phone_number", None)
            and getattr(room_metadata, "candidate_phone_number", None) != "unknown"
        )

        # If we have either opportunity_id or valid phone numbers, we don't need participant data
        if has_opportunity_id or has_phone_numbers:
            return False

        # Otherwise, we need to check participants
        return True

    async def _get_participant_data(self) -> Optional[ParticipantMetadata]:
        """Check participants and extract data based on participant type"""
        try:
            # List all participants in the room
            participants = await self.livekit_client.list_participants(self.room_name)

            logger.debug(
                "Checking participants",
                extra={
                    "room_name": self.room_name,
                    "participant_count": len(participants),
                },
            )

            # No participants found - this is only an error if we actually need participant data
            if not participants:
                logger.error(
                    "No participants found in room",
                    extra={"room_name": self.room_name},
                )
                raise ValueError(f"No participants found in room {self.room_name}")

            # First check for standard (non-SIP) participants
            for participant in participants:
                if self._is_standard_participant(participant):
                    standard_metadata = await self._get_standard_participant_data(
                        participant
                    )
                    if standard_metadata:
                        logger.info(
                            "Found standard participant with data",
                            extra={
                                "room_name": self.room_name,
                                "participant_identity": participant.identity,
                                "opportunity_id": getattr(
                                    standard_metadata, "opportunity_id", ""
                                ),
                            },
                        )
                        return standard_metadata

            # If no standard participant with data, check for SIP participants
            for participant in participants:
                if self._is_sip_participant(participant):
                    logger.info(
                        "Found SIP participant",
                        extra={
                            "room_name": self.room_name,
                            "participant_identity": participant.identity,
                            "participant_name": getattr(participant, "name", ""),
                        },
                    )

                    # Get detailed participant info
                    participant_details = (
                        await self.livekit_client.get_participant_details(
                            self.room_name, participant.identity
                        )
                    )

                    # Extract SIP attributes
                    sip_attrs = (
                        participant_details.attributes
                        if hasattr(participant_details, "attributes")
                        else {}
                    )

                    sip_metadata = SIPParticipantMetadata.from_dict(
                        {
                            "candidate_phone_number": sip_attrs.get(
                                "sip.phoneNumber", ""
                            ),
                            "agent_trunk_id": sip_attrs.get("sip.trunkID", ""),
                            "agent_phone_number": sip_attrs.get(
                                "sip.trunkPhoneNumber", ""
                            ),
                        }
                    )

                    logger.info(
                        "Extracted SIP call data",
                        extra={
                            "room_name": self.room_name,
                            "phone_number": sip_metadata.candidate_phone_number,
                            "trunk_id": sip_metadata.agent_trunk_id,
                            "agent_phone_number": sip_metadata.agent_phone_number,
                        },
                    )
                    return sip_metadata

            # No valid participant data found
            logger.warning(
                "No participant with valid data found",
                extra={"room_name": self.room_name},
            )
            return None

        except Exception as e:
            logger.error(
                "Failed to get participant data",
                extra={
                    "room_name": self.room_name,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            if "No participants found" in str(e):
                raise
            return None

    def _is_standard_participant(self, participant: Any) -> bool:
        """Check if participant is a standard (non-SIP) participant"""
        # A standard participant is one that is NOT a SIP participant
        is_standard = not self._is_sip_participant(participant)

        if is_standard:
            logger.debug(
                "Identified standard participant",
                extra={
                    "identity": getattr(participant, "identity", "unknown"),
                    "kind": getattr(participant, "kind", "unknown"),
                },
            )

        return is_standard

    async def _get_standard_participant_data(
        self, participant: Any
    ) -> Optional[StandardParticipantMetadata]:
        """Extract data from standard participant metadata"""
        try:
            # Get detailed participant info
            participant_details = await self.livekit_client.get_participant_details(
                self.room_name, participant.identity
            )

            # Check for metadata on the participant
            metadata = {}
            if (
                hasattr(participant_details, "metadata")
                and participant_details.metadata
            ):
                try:
                    metadata = json.loads(participant_details.metadata)
                except json.JSONDecodeError:
                    logger.warning(
                        "Failed to parse participant metadata",
                        extra={
                            "room_name": self.room_name,
                            "participant_identity": participant.identity,
                        },
                    )

            # Extract opportunity_id and internal_call_script_local_path from metadata if available
            if metadata.get("opportunity_id") or metadata.get(
                "internal_call_script_local_path"
            ):
                standard_metadata = StandardParticipantMetadata.from_dict(metadata)

                if metadata.get("internal_call_script_local_path"):
                    logger.info(
                        "Found internal_call_script_local_path in participant metadata",
                        extra={
                            "room_name": self.room_name,
                            "participant_identity": participant.identity,
                            "script_path": metadata["internal_call_script_local_path"],
                        },
                    )

                return standard_metadata

            return None

        except Exception as e:
            logger.error(
                "Failed to get standard participant data",
                extra={
                    "room_name": self.room_name,
                    "participant_identity": participant.identity,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            return None

    def _is_sip_participant(self, participant: Any) -> bool:
        """Check if participant is a SIP participant"""
        # Check by participant kind or identity pattern
        is_sip = (
            hasattr(participant, "kind")
            and str(participant.kind).upper() == "SIP"
            or (
                hasattr(participant, "identity")
                and str(participant.identity).lower().startswith("sip")
            )
        )

        if is_sip:
            logger.debug(
                "Identified SIP participant",
                extra={
                    "identity": getattr(participant, "identity", "unknown"),
                    "kind": getattr(participant, "kind", "unknown"),
                },
            )

        return is_sip

    async def _get_current_metadata(self) -> Optional[InputMetadata]:
        """Get and parse current room metadata as InputMetadata"""
        room_info = None
        try:
            room_info = self.ctx.room
            logger.debug("Room info", room_info=room_info)
            if room_info and room_info.metadata:
                metadata_dict = json.loads(room_info.metadata)

                # Parse the metadata dict into InputMetadata
                kind_str = metadata_dict.get("kind", CallKind.WEB.value)
                try:
                    kind = CallKind(kind_str)
                except ValueError:
                    logger.warning(
                        "Invalid call kind in room metadata, defaulting to WEB",
                        extra={
                            "room_name": self.room_name,
                            "invalid_kind": kind_str,
                        },
                    )
                    kind = CallKind.WEB

                # Create appropriate InputMetadata based on kind
                try:
                    if kind == CallKind.INBOUND:
                        input_metadata = InboundInputMetadata(
                            kind=CallKind.INBOUND,
                            candidate_phone_number=metadata_dict.get("candidate_phone_number", ""),
                            agent_phone_number=metadata_dict.get("agent_phone_number", ""),
                            agent_trunk_id=metadata_dict.get("agent_trunk_id", ""),
                            agent=metadata_dict.get("agent"),
                            internal_call_script_local_path=metadata_dict.get("internal_call_script_local_path"),
                            engagement_id=metadata_dict.get("engagement_id"),
                        )
                    elif kind == CallKind.OUTBOUND:
                        input_metadata = OutboundInputMetadata(
                            kind=CallKind.OUTBOUND,
                            candidate_phone_number=metadata_dict.get("candidate_phone_number", ""),
                            agent_trunk_id=metadata_dict.get("agent_trunk_id", ""),
                            opportunity_id=metadata_dict.get("opportunity_id", ""),
                            sequence_item_id=metadata_dict.get("sequence_item_id"),
                            agent=metadata_dict.get("agent"),
                            internal_call_script_local_path=metadata_dict.get("internal_call_script_local_path"),
                            engagement_id=metadata_dict.get("engagement_id"),
                        )
                    elif kind == CallKind.PLAYGROUND:
                        input_metadata = PlaygroundInputMetadata(
                            kind=CallKind.PLAYGROUND,
                            opportunity_id=metadata_dict.get("opportunity_id", ""),
                            sequence_item_id=metadata_dict.get("sequence_item_id"),
                            agent=metadata_dict.get("agent"),
                            internal_call_script_local_path=metadata_dict.get("internal_call_script_local_path"),
                            engagement_id=metadata_dict.get("engagement_id"),
                        )
                    else:  # Default to WEB
                        input_metadata = WebInputMetadata(
                            kind=CallKind.WEB,
                            opportunity_id=metadata_dict.get("opportunity_id", ""),
                            sequence_item_id=metadata_dict.get("sequence_item_id"),
                            agent=metadata_dict.get("agent"),
                            internal_call_script_local_path=metadata_dict.get("internal_call_script_local_path"),
                            engagement_id=metadata_dict.get("engagement_id"),
                        )

                    logger.info(
                        "Retrieved and parsed room metadata",
                        extra={
                            "room_name": self.room_name,
                            "metadata_kind": input_metadata.kind,
                            "has_phone": bool(getattr(input_metadata, "candidate_phone_number", None)),
                        },
                    )
                    return input_metadata

                except Exception as e:
                    logger.error(
                        "Failed to create InputMetadata from room metadata",
                        extra={
                            "room_name": self.room_name,
                            "metadata_dict": metadata_dict,
                            "error_type": type(e).__name__,
                        },
                        exc_info=True,
                    )
                    return None

            logger.info(
                "No existing room metadata found", extra={"room_name": self.room_name}
            )
            return None

        except json.JSONDecodeError:
            logger.error(
                "Failed to parse room metadata",
                extra={
                    "room_name": self.room_name,
                    "raw_metadata": room_info.metadata if room_info else None,
                },
                exc_info=True,
            )
            return None
        except Exception as e:
            logger.error(
                "Failed to get room metadata",
                extra={
                    "room_name": self.room_name,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            return None

    def _build_final_metadata(
        self,
        room_metadata: Optional[Dict[str, Any]],
        participant_data: Optional[ParticipantMetadata],
    ) -> InputMetadata:
        """Build final input metadata prioritizing room metadata over participant data"""

        # Start with room metadata as priority
        metadata_dict = room_metadata.copy() if room_metadata else {}

        # Merge participant data without overwriting existing room metadata
        if participant_data:
            participant_dict = participant_data.model_dump()
            for key, value in participant_dict.items():
                # Only add if not already in room metadata or if room metadata value is empty
                if key not in metadata_dict or not metadata_dict.get(key):
                    metadata_dict[key] = value

        # Determine call kind - prioritize room metadata, then participant data
        if metadata_dict.get("kind"):
            kind_str = metadata_dict["kind"]
        elif participant_data:
            kind_str = participant_data.kind.value
        else:
            kind_str = CallKind.WEB.value

        try:
            kind = CallKind(kind_str)
        except ValueError:
            logger.warning(
                "Invalid call kind in metadata, defaulting to WEB",
                extra={
                    "room_name": self.room_name,
                    "invalid_kind": kind_str,
                },
            )
            kind = CallKind.WEB

        # Add defaults if missing
        if not metadata_dict.get("candidate_phone_number"):
            metadata_dict["candidate_phone_number"] = ""
        if not metadata_dict.get("agent_trunk_id"):
            metadata_dict["agent_trunk_id"] = ""

        # Create appropriate input metadata object based on kind
        try:
            final_input_metadata: InputMetadata

            # Check for internal_call_script_local_path
            internal_call_script_local_path = metadata_dict.get(
                "internal_call_script_local_path"
            )
            if internal_call_script_local_path:
                logger.info(
                    "Setting internal_call_script_local_path in room metadata",
                    extra={
                        "room_name": self.room_name,
                        "script_path": internal_call_script_local_path,
                    },
                )

            if kind == CallKind.INBOUND:
                final_input_metadata = InboundInputMetadata(
                    candidate_phone_number=metadata_dict.get(
                        "candidate_phone_number", ""
                    ),
                    agent=metadata_dict.get("agent", AgentType.SCREENING),
                    agent_trunk_id=metadata_dict.get("agent_trunk_id", ""),
                    agent_phone_number=metadata_dict.get("agent_phone_number", ""),
                    internal_call_script_local_path=internal_call_script_local_path,
                    kind=CallKind.INBOUND,
                )
            elif kind == CallKind.OUTBOUND:
                final_input_metadata = OutboundInputMetadata(
                    candidate_phone_number=metadata_dict.get(
                        "candidate_phone_number", ""
                    ),
                    agent_trunk_id=metadata_dict.get("agent_trunk_id", ""),
                    agent=metadata_dict.get("agent", AgentType.SCREENING),
                    opportunity_id=metadata_dict.get("opportunity_id", ""),
                    sequence_item_id=metadata_dict.get("sequence_item_id"),
                    internal_call_script_local_path=internal_call_script_local_path,
                    kind=CallKind.OUTBOUND,
                )
            elif kind == CallKind.PLAYGROUND:
                final_input_metadata = PlaygroundInputMetadata(
                    agent=metadata_dict.get("agent", AgentType.SCREENING),
                    opportunity_id=metadata_dict.get("opportunity_id", ""),
                    sequence_item_id=metadata_dict.get("sequence_item_id"),
                    internal_call_script_local_path=internal_call_script_local_path,
                    kind=CallKind.PLAYGROUND,
                )
            else:  # Default to WEB
                final_input_metadata = WebInputMetadata(
                    agent=metadata_dict.get("agent", AgentType.SCREENING),
                    opportunity_id=metadata_dict.get("opportunity_id", ""),
                    sequence_item_id=metadata_dict.get("sequence_item_id"),
                    internal_call_script_local_path=internal_call_script_local_path,
                    kind=CallKind.WEB,
                )

            logger.info(
                "Built final input metadata",
                extra={
                    "room_name": self.room_name,
                    "kind": final_input_metadata.kind,
                    "input_metadata": final_input_metadata,
                },
            )
            return final_input_metadata

        except Exception as e:
            logger.error(
                "Failed to build input metadata, using defaults",
                extra={
                    "room_name": self.room_name,
                    "metadata_dict": metadata_dict,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            # Return a default web metadata on error
            return WebInputMetadata(
                kind=CallKind.WEB,
                agent=metadata_dict.get("agent", AgentType.SCREENING),
                opportunity_id=metadata_dict.get("opportunity_id", ""),
                sequence_item_id=metadata_dict.get("sequence_item_id"),
                internal_call_script_local_path=metadata_dict.get(
                    "internal_call_script_local_path"
                ),
            )

    async def _create_engagement(
        self, metadata: InputMetadata
    ) -> Optional[CreateEngagementResponse]:
        """Create engagement with Purplefish API using available data"""
        try:
            # Prepare parameters based on available data
            # Priority: 1. opportunity_id from room metadata, 2. phone numbers for inbound

            opportunity_id = getattr(metadata, "opportunity_id", None)
            candidate_phone_number = getattr(metadata, "candidate_phone_number", None)
            agent_phone_number = getattr(metadata, "agent_phone_number", None)

            # Use opportunity_id if available (highest priority)
            if opportunity_id and opportunity_id != "":
                result = await self.purplefish_client.create_engagement(
                    room_name=self.room_name,
                    opportunity_id=opportunity_id,
                )
                logger.info(
                    "Created engagement with opportunity_id",
                    extra={
                        "room_name": self.room_name,
                        "opportunity_id": opportunity_id,
                    },
                )
            # Otherwise use phone numbers if available (for inbound calls)
            elif candidate_phone_number and candidate_phone_number != "unknown":
                result = await self.purplefish_client.create_engagement(
                    room_name=self.room_name,
                    candidate_phone_number=candidate_phone_number,
                    agent_phone_number=agent_phone_number,
                )
                logger.info(
                    "Created engagement with phone numbers",
                    extra={
                        "room_name": self.room_name,
                        "candidate_phone_number": candidate_phone_number,
                        "agent_phone_number": agent_phone_number,
                    },
                )
            else:
                # Fallback: create engagement with just room_name
                result = await self.purplefish_client.create_engagement(
                    room_name=self.room_name,
                )
                logger.info(
                    "Created engagement with room_name only",
                    extra={
                        "room_name": self.room_name,
                    },
                )

            logger.info(
                "Engagement created successfully",
                extra={
                    "room_name": self.room_name,
                    "engagement_id": result.engagement_id,
                    "agent_name": result.agent_name or "not_specified",
                    "metadata_kind": metadata.kind,
                },
            )
            return result

        except Exception as e:
            logger.error(
                "Failed to create engagement, continuing with default agent",
                extra={
                    "room_name": self.room_name,
                    "metadata_kind": metadata.kind,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            return None

    def _create_agent_room_metadata(
        self,
        input_metadata: InputMetadata,
        participant_metadata: Optional[ParticipantMetadata],
        engagement_id: str,
    ) -> ScreeningAgentRoomMetadata:
        """Create AgentRoomMetadata by combining input and participant metadata"""
        return ScreeningAgentRoomMetadata.from_input_and_participant(
            input_metadata=input_metadata,
            participant_metadata=participant_metadata,
            engagement_id=engagement_id,
        )

    async def _update_room_metadata(self, metadata: ScreeningAgentRoomMetadata) -> None:
        """Update room metadata in LiveKit with AgentRoomMetadata"""
        try:
            metadata_json = json.dumps(metadata.model_dump())
            await self.livekit_client.update_room_metadata(
                self.room_name, metadata_json
            )

            logger.info(
                "Updated room metadata with AgentRoomMetadata",
                extra={
                    "room_name": self.room_name,
                    "engagement_id": metadata.engagement_id,
                    "metadata_kind": metadata.input_metadata.kind,
                    "metadata_size": len(metadata_json),
                },
            )
        except Exception as e:
            logger.error(
                "Failed to update room metadata",
                extra={
                    "room_name": self.room_name,
                    "metadata_kind": metadata.input_metadata.kind,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            raise

    async def _dispatch_agent(self, metadata: ScreeningAgentRoomMetadata) -> None:
        """Dispatch screening agent to the room with AgentRoomMetadata"""
        try:
            input_metadata = metadata.input_metadata
            if input_metadata.kind == CallKind.OUTBOUND:
                outbound_metadata = (
                    input_metadata  # Already typed as OutboundInputMetadata
                )
                await self.livekit_client.make_outbound_call(
                    outbound_trunk_id=outbound_metadata.agent_trunk_id,
                    room_name=self.ctx.job.room.name,
                    number=outbound_metadata.candidate_phone_number,
                    participant_name="sip_outbound_participant",
                )

            # Convert metadata to JSON for dispatch
            metadata_json = json.dumps(metadata.model_dump())

            # Dispatch the screening agent
            dispatch_result = await self.livekit_client.dispatch_agent(
                agent_name=input_metadata.agent or AgentType.SCREENING,
                room_name=self.room_name,
                metadata=metadata_json,
            )

            logger.info(
                "Dispatched screening agent with AgentRoomMetadata",
                extra={
                    "room_name": self.room_name,
                    "dispatch_id": dispatch_result.get("dispatch_id"),
                    "metadata_kind": input_metadata.kind,
                    "engagement_id": metadata.engagement_id,
                    "job_id": self.ctx.job.id if self.ctx.job else None,
                },
            )
        except Exception as e:
            logger.error(
                "Failed to dispatch agent",
                extra={
                    "room_name": self.room_name,
                    "metadata": metadata,
                    "error_type": type(e).__name__,
                },
                exc_info=True,
            )
            raise e
